using System;
using System.IO;
using System.Linq;
using System.Text;
class MarketHistoryTests {
 static void Check(bool condition,string message){if(!condition)throw new Exception(message);}
 public static void Run(){
 Encoding.RegisterProvider(CodePagesEncodingProvider.Instance);
 var today=DateTime.UtcNow.AddHours(8).Date;long t=MarketSessions.Utc(today.AddHours(9));string month=today.ToString("yyyyMM"),code=MonthlyContract.SymbolFor("TXF",month),option=MarketCsv.OptionSymbol(month,22000,"call");
 Check(MarketSessions.Kind(MarketSessions.Utc(today.AddHours(2)))=="night"&&MarketSessions.Date(MarketSessions.Utc(today.AddHours(2)))==today.AddDays(-1).ToString("yyyy-MM-dd"),"night anchor");Check(MarketSessions.Kind(MarketSessions.Utc(today.AddHours(8)))=="off","session gap");
 var root=Path.Combine(Path.GetTempPath(),"tanyasite-history-tests-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);try{
 var a=new MarketArchive(root);a.Trade(code,"future",0,22000,299,"buy",t,200,"live",1);a.Trade(code,"future",0,22100,300,"sell",t+1000,200,"live",2);a.Trade(code,"future",0,22030,400,"unknown",t+2000,200,"live",3);a.Trade(code,"future",0,22130,1,"buy",t+3000,200,"live",4);a.Trade(option,"call",22000,200,49,"buy",t,50,"live",5);a.Trade(option,"call",22000,200,50,"buy",t+1000,50,"live",6);
 var summary=a.Summary(t+60000,code);var f=summary.weekly.Single(m=>m.symbol==code);Check(f.volume==1000&&f.buyQty==300&&f.largeSellQty==300&&f.largeUnknownQty==400,"weekly quantities and 300 boundary");Check(summary.sessions.Single().pivots.Count>=2&&a.Recent(code,50).Count==1,"raw tick waves independent of minute candles");Check(a.Big(null,50).Count==3&&a.Big(null,50).Single(x=>x.kind=="call").premiumAmount==500000,"50 boundary and premium formula");a.Flush();var restored=new MarketArchive(root);Check(restored.Summary(t+60000,code).weekly.Single(m=>m.symbol==code).volume==1000,"restart persistence");
 var historical=new MarketArchive(null);historical.Trade(code,"future",0,22001,300,"unknown",t,200,"history:one",1);restored.ImportHistorical(historical,"official sample");restored.ImportHistorical(historical,"official sample");Check(restored.Summary(t+60000,code).weekly.Single(m=>m.symbol==code).volume==300,"idempotent replacement, no live/history double count");Check(restored.Big(null,50).Count(x=>x.symbol==code)==1,"dedupe historical big trades");Check(new MarketArchive(root).Big(null,50).Count(x=>x.symbol==code)==1,"persistent tombstones");
 var unordered=new MarketArchive(null);unordered.Trade(code,"future",0,22000,1,"unknown",t+3000,200,"x",1);unordered.Trade(code,"future",0,22100,1,"unknown",t+1000,200,"x",2);var us=unordered.Summary(t+60000,code).sessions.Single();Check(us.unordered&&us.pivots.Count==0&&us.close==22000&&us.open==22100,"unsorted source disables wave and preserves chronological OHLC");
 restored.Trade(code,"future",0,22000,9,"unknown",MarketSessions.Utc(today.AddDays(-7).AddHours(9)),200,"old",1);Check(restored.Summary(t+60000,code).weekly.Single(m=>m.symbol==code).volume==300,"rolling seven calendar days cutoff");
 var csv="成交日期,商品代號,到期月份(週別),成交時間,成交價格,成交數量(B+S),履約價格,買賣權別\n"+today.ToString("yyyyMMdd")+",TX,"+month+",090000,22000,600,,\n"+today.ToString("yyyyMMdd")+",TXO,"+month+",090001,200,100,22000,C\n";var path=Path.Combine(root,"ticks.csv");File.WriteAllText(path,csv,new UTF8Encoding(false));var ticks=new TickHistory();var imported=new MarketArchive(null);Check(ticks.Import(path,month,imported,"test official layout")==2,"tick CSV accepted");Check(imported.Summary(t+60000,code).weekly.Single(m=>m.kind=="future").volume==300,"B+S halved only explicit header");File.WriteAllText(path,csv.Replace("600,,","601,,"));bool rejected=false;try{ticks.Import(path,month,imported,"bad sample");}catch(InvalidDataException){rejected=true;}Check(rejected,"odd B+S rejected instead of rounding");
 var daily=new TaifexDailyStore(root);var header="交易日期,契約,到期月份(週別),成交量,未沖銷契約數,交易時段\n";var reports=header+today.AddDays(-8).ToString("yyyy/MM/dd")+",TX,"+month+",10,100,一般\n"+today.AddDays(-2).ToString("yyyy/MM/dd")+",TX,"+month+",20,120,一般\n"+today.AddDays(-1).ToString("yyyy/MM/dd")+",TX,"+month+",30,125,一般\n"+today.AddDays(-1).ToString("yyyy/MM/dd")+",TX,"+month+",15,999,盤後\n";daily.Import(reports,"official-shaped fixture");var oi=daily.Week(month,today).Single();Check(oi.openInterest==125&&oi.dailyChange==5&&oi.weekChange==25&&oi.reportedVolume==65,"OI stock change vs weekly volume, day OI only");Check(new TaifexDailyStore(root).Week(month,today).Single().weekChange==25,"OI persistence");var fresh=new TaifexDailyStore(Path.Combine(root,"missing"));fresh.Import(header+today.ToString("yyyy/MM/dd")+",TX,"+month+",0,0,一般\n","zero fixture");Check(fresh.Week(month,today).Single().openInterest==0&&fresh.Week(month,today).Single().weekChange==null,"zero OI versus absent baseline");
 var now=new DateTime(2026,10,21,13,31,0);var contracts=new[]{MonthlyContract.Parse("TXFJ6","20261021",now),MonthlyContract.Parse("TXFK6","20261118",now),MonthlyContract.Parse("TXFC7","20270317",now)};Check(MonthlyContract.Choose(contracts,now,true).Symbol=="TXFK6","near rollover after settlement");Check(MonthlyContract.Choose(contracts,now,false)==null,"calendar month expiry does not silently choose far month");Check(MonthlyContract.MonthFor("TXO22000V6",now)=="202610","put month mapping");Check(OptionChain.Select(Enumerable.Range(0,10).SelectMany(i=>new[]{OptionDescriptor.Parse("TXO"+(22000+i*50)+"J6","20261021",22000+i*50,"C"),OptionDescriptor.Parse("TXO"+(22000+i*50)+"V6","20261021",22000+i*50,"P")}),22000,8).Count==16,"three futures leave sixteen options under twenty cap");
 Console.WriteLine("PASS: persistent week archive, night dates, raw-tick waves, 300/50 thresholds, premium, dedupe/import, OI deltas, month rollover and subscription budget.");
 }finally{Directory.Delete(root,true);}
 }
}
